/// Rows `[vx, vy, vz]` of the MFEM `CalcVShape` dump at sample point `q`.
pub(super) fn v(p: usize, q: usize) -> Vec<[f64; 3]> {
    match (p, q) {
        (1, 0) => V_1_0.to_vec(),
        (1, _) => V_1_1.to_vec(),
        (2, 0) => V_2_0.to_vec(),
        (2, _) => V_2_1.to_vec(),
        _ => panic!("no MFEM hex RT nodal-GL dump for p = {p}"),
    }
}

/// Entries of the MFEM `CalcDivShape` dump at sample point `q`.
pub(super) fn div(p: usize, q: usize) -> Vec<f64> {
    match (p, q) {
        (1, 0) => X_1_0.to_vec(),
        (1, _) => X_1_1.to_vec(),
        (2, 0) => X_2_0.to_vec(),
        (2, _) => X_2_1.to_vec(),
        _ => panic!("no MFEM hex RT nodal-GL dump for p = {p}"),
    }
}
